// Builds supabase/functions/plops-single-file/index.ts: the plops Edge Function as ONE file,
// for pasting into the Supabase dashboard editor (no command line needed).
//   node scripts/bundle-function.mjs
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';

const dir = 'supabase/functions/plops';
const strip = (src) => src.replace(/^import [^;]+ from '\.\/[a-z]+\.ts';\n/gm, '');
const out = [
  '// GENERATED by scripts/bundle-function.mjs from supabase/functions/plops/*.ts. Do not edit by hand.',
  '// Paste this whole file into the Supabase dashboard as the `plops` Edge Function.',
  '',
  '// ---- validate.ts ----',
  strip(readFileSync(`${dir}/validate.ts`, 'utf8')),
  '// ---- core.ts ----',
  strip(readFileSync(`${dir}/core.ts`, 'utf8')).replace(/token as parseToken/g, ''),
  '// ---- index.ts ----',
  strip(readFileSync(`${dir}/index.ts`, 'utf8')),
].join('\n');
const fixed = out.replace(/\bparseToken\(/g, 'token(');
mkdirSync('supabase/functions/plops-single-file', { recursive: true });
writeFileSync('supabase/functions/plops-single-file/index.ts', fixed);
console.log('Wrote supabase/functions/plops-single-file/index.ts');
